// ⚠️ PACE ADJUSTMENT FACTOR
// Client threshold paces in TrainingPeaks are set to ~95% of dream marathon pace
// Small 5% adjustment to align workouts correctly
// This factor converts standard %TP to adjusted values
const PACE_FACTOR = 1.05;

// Helper to adjust percentages
function adj(pct) {
  return Math.round(pct * PACE_FACTOR);
}

// Helper to format pace range
