// ==========================================
// INTELLIGENT WEEKLY SELECTION
// Always includes: beginner long, marathon, standard long, race-specific
// ==========================================
function selectWeeklyWorkouts() {
  const today = new Date();
  const weekNum = Math.floor((today - new Date(today.getFullYear(), 0, 1)) / (7 * 24 * 60 * 60 * 1000));
  const selectedWorkouts = [];
  const usedNames = new Set();

  function pickRandom(arr) {
    const available = arr.filter(w => !usedNames.has(w.name));
    if (available.length === 0) return arr[Math.floor(Math.random() * arr.length)];
    const picked = available[Math.floor(Math.random() * available.length)];
    usedNames.add(picked.name);
    return picked;
  }

  // 1. ALWAYS: Beginner Long Run option
  selectedWorkouts.push(pickRandom(workouts.beginnerLong));

  // 2. ALWAYS: Marathon Session
  selectedWorkouts.push(pickRandom(workouts.marathon));

  // 3. ALWAYS: Standard Long Run
  selectedWorkouts.push(pickRandom(workouts.longRun));

  // 4. RACE SPECIFIC: Rotate 5K → 10K → Half Marathon
  const raceRotation = [workouts.fiveK, workouts.tenK, workouts.halfMarathon];
  selectedWorkouts.push(pickRandom(raceRotation[weekNum % 3]));

  // 5. QUALITY: VO2 or Tempo/Threshold (alternate)
  if (weekNum % 2 === 0) {
    selectedWorkouts.push(pickRandom(workouts.vo2max));
  } else {
    selectedWorkouts.push(pickRandom(workouts.tempo));
  }

  // 6. SPEED: Track or intervals
  selectedWorkouts.push(pickRandom(workouts.speed));

  // 7. EASY: Recovery option
  selectedWorkouts.push(pickRandom(workouts.easy));

  return selectedWorkouts;
}

// Apply pace adjustment to percentage strings
function adjustPaces(text) {
  // Match patterns like "70-75%" or "@ 86-90%" or "105%"
  return text.replace(/(\d+)-(\d+)%/g, (match, low, high) => {
    return `${adj(parseInt(low))}-${adj(parseInt(high))}%`;
  }).replace(/(@ |: )(\d+)%/g, (match, prefix, pct) => {
    return `${prefix}${adj(parseInt(pct))}%`;
  });
}

