function formatWorkout(workout, index) {
  const adjustedBreakdown = workout.breakdown.map(line => adjustPaces(line));
  const breakdownText = adjustedBreakdown.map(line => `  • ${line}`).join('\n');
  const adjustedTP = adjustPaces(workout.trainingPeaks);
  return `\n*${index}. ${workout.name}*\n🏷️ _${workout.type}_\n\n📝 *Description:*\n${workout.description}\n\n📊 *Breakdown (adjusted for dream MP as TP):*\n${breakdownText}\n\n🔧 *TrainingPeaks Build:*\n\`${adjustedTP}\`\n`;
}

